from itertools import combinations
P={'A':(77,45),'P1':(77,133),'B':(180,133),'Q':(77,210),'U':(77,355),'R':(185,210),'S':(240,250),'T':(185,285)}
# X = intersection of B-Q and P1-S
def inter(a,b,c,d):
    (x1,y1),(x2,y2),(x3,y3),(x4,y4)=a,b,c,d
    den=(x1-x2)*(y3-y4)-(y1-y2)*(x3-x4)
    t=((x1-x3)*(y3-y4)-(y1-y3)*(x3-x4))/den
    return (x1+t*(x2-x1),y1+t*(y2-y1))
P['X']=inter(P['B'],P['Q'],P['P1'],P['S'])
lines=[['A','P1','Q','U'],['A','B'],['P1','B'],['B','X','Q'],['P1','X','R','S'],['Q','R'],['R','T'],['S','T','U'],['Q','T']]
def on(a,b):
    return any(a in l and b in l for l in lines)
def col(a,b,c):
    (x1,y1),(x2,y2),(x3,y3)=P[a],P[b],P[c]
    return abs((x2-x1)*(y3-y1)-(y2-y1)*(x3-x1))<1e-6*1e4
n=0
for a,b,c in combinations(P,3):
    if on(a,b) and on(b,c) and on(a,c) and not any(a in l and b in l and c in l for l in lines):
        n+=1
opts={'A':13,'B':12,'C':11,'D':10}
assert n==opts['C'],n
for k in 'ABD': assert n!=opts[k]

